{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, a close retinoid analogue sharing the same conjugated tetraene and cyclohexene ring, has a systemic bioavailability of 40% after oral capsule dosing, directly supporting F ≥ 20% for the retinoid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a retinoid acid, has an absolute oral bioavailability of approximately 60% (range 36–95%) after a single oral dose with food, showing that retinoid-class molecules typically exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Etretinate, a highly lipophilic neutral retinoid ester, has an absolute oral bioavailability of about 40%, indicating that even non-ionizable, poorly water-soluble retinoid derivatives can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "All-trans retinoic acid oral bioavailability was estimated at no more than 25–30% in healthy volunteers, providing a lower-bound retinoid estimate that still meets the F ≥ 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Paracetamol, which shares the p-hydroxyanilide moiety with the query, has an absolute oral bioavailability of 63%, supporting that the polar amide/phenol head group does not inherently preclude good absorption, though transferability is limited by size differences.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a fenretinide-like retinoid amide. The closest retinoid analogues (isotretinoin, tretinoin, acitretin, etretinate) consistently show oral bioavailability values of roughly 25–60%, all above the 20% threshold. The shared p-hydroxyanilide with paracetamol further supports absorption. Although some retinoid reports describe variable or low bioavailability, none affirmatively establish F < 20%, so high is better supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself; extrapolation relies on retinoid acid/ester analogues and the paracetamol-like head group.",
    "Some retinoid records report 'low' or 'erratic' bioavailability without numeric values, so a threshold-specific F < 20% cannot be affirmed from those records.",
    "Formulation and fed/fasted state are unspecified for the query; retinoid absorption is strongly influenced by food and formulation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

